// ✅ The request reaches WorkManager's database before enqueue() returns
fun upload(context: Context, uri: Uri) {
  val request = OneTimeWorkRequestBuilder<UploadWorker>()
    .setInputData(workDataOf("uri" to uri.toString()))
    .setConstraints(
      Constraints.Builder()
        .setRequiredNetworkType(NetworkType.CONNECTED)
        .build()
    )
    .build()

  // Unique name: five impatient taps do not become five uploads
  WorkManager.getInstance(context)
    .enqueueUniqueWork("upload:$uri", ExistingWorkPolicy.KEEP, request)
}

