class UploadWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
  override suspend fun doWork(): Result {
    val path = inputData.getString("path") ?: return Result.failure()
    val album = inputData.getLong("albumId", -1L)

    val remoteId = api.upload(File(path), album) { percent ->
      // Live-only: this disappears the moment the work finishes
      setProgress(workDataOf("percent" to percent))
    }

    File(path).delete()
    // Output is capped too — return an id, not the response body
    return Result.success(workDataOf("remoteId" to remoteId))
  }
}

