class BackupWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {

  override suspend fun doWork(): Result {
    val queuedAt = inputData.getLong("queuedAt", 0L)
    // Nothing expires an unsatisfiable constraint — decide staleness yourself
    if (System.currentTimeMillis() - queuedAt > 7.days.inWholeMilliseconds) {
      return Result.success()
    }

    // The run restarts from the top, so skip whatever an earlier attempt finished
    for (photo in dao.pendingPhotos()) {
      currentCoroutineContext().ensureActive()
      api.upload(photo)
      dao.markUploaded(photo.id)     // commit per item, never once at the end
    }
    return Result.success()
  }

  override fun onStopped() {
    // Main thread, called when the constraint drops, the user cancels,
    // or you blow the execution window. Do not block here.
    Log.i("backup", "stopped, reason=$stopReason")
  }
}

