class SyncWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {

  override suspend fun doWork(): Result = try {
    api.sync()
    Result.success()
  } catch (e: HttpException) {
    // 5xx and 429 may pass; 4xx will give the same answer forever
    if (e.code() == 429 || e.code() >= 500) retryUpTo(5) else giveUp(e.message())
  } catch (e: IOException) {
    retryUpTo(5)                       // offline, DNS, timeout
  }

  // runAttemptCount is 0 on the first run, so this allows six attempts in total
  private fun retryUpTo(maxAttempts: Int): Result =
    if (runAttemptCount >= maxAttempts) giveUp("out of attempts") else Result.retry()

  private fun giveUp(reason: String): Result {
    dao.markSyncFailed(reason)         // the user has to be able to see this
    return Result.failure()
  }
}

