// ✅ Cooperative: poll the flag the system sets
class CopyWorker(ctx: Context, p: WorkerParameters) : Worker(ctx, p) {
  override fun doWork(): Result {
    for (file in files) {
      if (isStopped) return Result.retry()   // the run restarts from the top later
      copy(file)
    }
    return Result.success()
  }
}

// CoroutineWorker: a stop cancels the coroutine, so cleanup is structural
class SyncWorker(ctx: Context, p: WorkerParameters) : CoroutineWorker(ctx, p) {
  override suspend fun doWork(): Result = withContext(Dispatchers.IO) {
    try {
      for (file in files) {
        currentCoroutineContext().ensureActive()
        upload(file)
      }
      Result.success()
    } catch (e: CancellationException) {
      throw e            // a bare catch (e: Exception) would have swallowed this
    } catch (e: IOException) {
      Result.retry()
    } finally {
      tempDir.deleteRecursively()            // runs on cancellation too
    }
  }

  override fun onStopped() {
    Log.i("sync", "stopped, reason=$stopReason")   // main thread: do not block
  }
}

