class AlarmScheduler(private val ctx: Context, private val dao: AlarmDao) {

  private val am = ctx.getSystemService(AlarmManager::class.java)

  fun armNext() {
    val next = dao.nextEnabled() ?: return
    if (!am.canScheduleExactAlarms()) {            // denied by default on 14+
      ctx.startActivity(Intent(ACTION_REQUEST_SCHEDULE_EXACT_ALARM))
      return
    }
    val fire = PendingIntent.getBroadcast(
      ctx, next.id,
      Intent(ctx, AlarmReceiver::class.java).putExtra("id", next.id),
      PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
    )
    // setExact would be deferred by Doze; setAlarmClock is exempt and shows
    // the status-bar icon, whose tap target is the second PendingIntent.
    am.setAlarmClock(AlarmManager.AlarmClockInfo(next.timeMillis, showUi()), fire)
  }
}

class AlarmReceiver : BroadcastReceiver() {
  override fun onReceive(ctx: Context, intent: Intent) {
    ring(ctx, intent.getIntExtra("id", 0))
    AlarmScheduler(ctx, dao(ctx)).armNext()        // always arm the next one
  }
}

// Reboot and app update wipe every pending alarm — rebuild from the database
class BootReceiver : BroadcastReceiver() {
  override fun onReceive(ctx: Context, intent: Intent) {
    AlarmScheduler(ctx, dao(ctx)).armNext()
  }
}

