// Snapshot the restrictions in play, attach it to your sync telemetry
data class BackgroundHealth(
  val manufacturer: String,
  val bucket: String,
  val batteryOptimised: Boolean,
  val backgroundRestricted: Boolean,
)

fun backgroundHealth(ctx: Context): BackgroundHealth {
  val power = ctx.getSystemService(PowerManager::class.java)
  val usage = ctx.getSystemService(UsageStatsManager::class.java)
  val activity = ctx.getSystemService(ActivityManager::class.java)

  return BackgroundHealth(
    manufacturer = Build.MANUFACTURER,
    bucket = when (usage.appStandbyBucket) {
      UsageStatsManager.STANDBY_BUCKET_ACTIVE -> "active"
      UsageStatsManager.STANDBY_BUCKET_WORKING_SET -> "working_set"
      UsageStatsManager.STANDBY_BUCKET_FREQUENT -> "frequent"
      UsageStatsManager.STANDBY_BUCKET_RARE -> "rare"
      else -> "restricted"                    // ~one job window per day
    },
    // false here means the vendor or the user is deferring you
    batteryOptimised = !power.isIgnoringBatteryOptimizations(ctx.packageName),
    backgroundRestricted = activity.isBackgroundRestricted,
  )
}

// The design that survives all of it: the periodic job is a bonus,
// the foreground path is the mechanism.
class SyncGate @Inject constructor(private val repo: SyncRepository) {
  fun onAppForegrounded() = repo.syncIfStale(maxAge = 15.minutes)
}

class AppMessagingService : FirebaseMessagingService() {

  override fun onMessageReceived(message: RemoteMessage) {
    // Was our high priority honoured, or did FCM downgrade us for sending
    // high-priority data messages that never produced a notification?
    if (message.priority != message.originalPriority) {
      analytics.log("fcm_priority_downgraded")
    }

    // Seconds, not minutes: hand off and return.
    val version = message.data["version"]?.toLongOrNull() ?: return
    if (version <= store.localVersion) return          // already current

    val sync = OneTimeWorkRequestBuilder<SyncWorker>()
      .setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST)
      .setInputData(workDataOf("target_version" to version))
      .build()

    // KEEP: a burst of ten pushes collapses into one sync
    WorkManager.getInstance(this)
      .enqueueUniqueWork("sync", ExistingWorkPolicy.KEEP, sync)
  }
}

